        recursion_frequency: this.selectTriggerAction,
        recursion_date: this.selectTriggerAction == "MONTHLY" || this.selectTriggerAction == "FORTNIGHTLY" || this.selectTriggerAction == "BI_MONTHLY" || this.selectTriggerAction == "QUATERLY" || this.selectTriggerAction == "HALFYEARLY" || this.selectTriggerAction == "YEARLY" ? this.selectDate : undefined,
