        completion_days: this.selectTriggerAction != "DAILY" ? this.completionBefore : undefined,
        recursion_month: this.selectTriggerAction == "QUATERLY" || this.selectTriggerAction == "HALFYEARLY" || this.selectTriggerAction == "YEARLY" ? this.selectMonth : undefined
      };
      return JSON.stringify(data);
